            },
            {
                time: "6:00 PM - Golden Hour",
                acts: [
                    { id: "3a", name: "Legacy Rock Act", stage: "Main Stage", energy: -15, loyalty: +5, isMustSee: true, desc: "They only play their hits from 2004. Perfect sunset vibes." },
