        function updateStats() {
            let energy = 100;
            let loyalty = 100;
            let distance = 0;
            let caughtMustSees = 0;
            let lastStageIndex = null;

            // Ensure we iterate in chronological order
            const sortedIndices = Object.keys(selectedActs).sort((a, b) => a - b);

            sortedIndices.forEach(idx => {
                const act = selectedActs[idx];
                energy += act.energy;
                loyalty += act.loyalty;
                if (act.isMustSee) caughtMustSees++;

                const currentStageIndex = STAGES[act.stage];
                if (lastStageIndex !== null) {
                    distance += Math.abs(currentStageIndex - lastStageIndex) * 0.5; // 0.5 miles per stage gap
                }
                lastStageIndex = currentStageIndex;
            });

            // Clamp values
            if (energy < 0) energy = 0;
            if (energy > 100) energy = 100;
            if (loyalty < 0) loyalty = 0;
            if (loyalty > 100) loyalty = 100;

            // Update DOM
            const eSpan = document.getElementById('val-energy');
            eSpan.textContent = `${energy}%`;
            eSpan.className = `stat-value ${energy < 20 ? 'danger' : energy < 50 ? 'warning' : ''}`;

            const lSpan = document.getElementById('val-loyalty');
            lSpan.textContent = `${loyalty}%`;
            lSpan.className = `stat-value ${loyalty < 30 ? 'danger' : loyalty < 60 ? 'warning' : ''}`;

            document.getElementById('val-distance').textContent = `${distance.toFixed(1)} mi`;
            document.getElementById('val-mustsee').textContent = `${caughtMustSees}/${totalMustSees}`;
        }

        function checkExportState() {
            const btn = document.getElementById('export-btn');
            if (Object.keys(selectedActs).length === scheduleData.length) {
                btn.disabled = false;
                btn.textContent = "📋 Copy Route & Brag";
            }
        }

        function exportRoute() {
            let energy = parseInt(document.getElementById('val-energy').textContent);
            let loyalty = parseInt(document.getElementById('val-loyalty').textContent);
            let distance = document.getElementById('val-distance').textContent;
            let mustsee = document.getElementById('val-mustsee').textContent;

            let vibeCheck = "";
            if (energy === 0) vibeCheck = "Literally passed out in an Uber line.";
            else if (loyalty < 30) vibeCheck = "Your friends are ignoring your texts.";
            else if (energy > 50 && loyalty > 80) vibeCheck = "Festival God. Perfect balance.";
            else vibeCheck = "Survived the chaos.";

            let routeText = `🎡 MY FESTIVAL ROUTE ⛺\n`;
            routeText += `⚡ Energy Left: ${energy}% | 🤝 Squad Loyalty: ${loyalty}%\n`;
            routeText += `👟 Walked: ${distance} | ⭐ Must-Sees: ${mustsee}\n`;
            routeText += `Vibe Check: ${vibeCheck}\n\n`;

            const sortedIndices = Object.keys(selectedActs).sort((a, b) => a - b);
            sortedIndices.forEach(idx => {
                const timeStr = scheduleData[idx].time.split(' - ')[0];
                routeText += `[${timeStr}] ${selectedActs[idx].name} (@ ${selectedActs[idx].stage})\n`;
            });

            navigator.clipboard.writeText(routeText).then(() => {
                const toast = document.getElementById('toast');
                toast.style.opacity = '1';
                setTimeout(() => { toast.style.opacity = '0'; }, 3000);
            });
        }

        // Boot it up
        init();
    </script>
